{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 조례상 대여소 간 상호호환이 가능한 공공자전거 무인대여시스템 구축 허용 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "조례는 시장이 공공자전거를 구비하고 대여할 수 있는 시설을 설치·운영할 수 있도록 하면서, 그 경우 공공자전거 대여소 간 상호호환이 가능한 공공자전거 무인대여시스템으로 구축·운영할 수 있다고 정하고 있다. 따라서 대여소 간 상호호환이 가능한 공공자전거 무인대여시스템 구축 방식은 조례에서 허용된다.",
          "b_ids": "자전거:제12조의2제1항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "서울특별시 조례상 공공자전거 무인대여시스템 설치·운영의 공공기관 위탁 및 비용 지원 허용 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "조례는 시장이 제1항에 따른 공공자전거 시스템등의 설치·운영을 공공기관 또는 민간에게 위탁할 수 있다고 정하고, 예산의 범위에서 그 비용을 지원할 수 있다고 정하고 있다. 따라서 설치·운영을 공공기관에 위탁하는 방식과 예산의 범위에서 비용을 지원하는 방식은 각각 조례에서 허용된다.",
          "b_ids": "자전거:제12조의2제2항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
